<table border="1" cellpadding="1" cellspacing="1"><tbody><tr><td>Options:</td><td>A</td><td>B</td><td>C</td><td>D</td></tr><tr><td>1.</td><td>III</td><td>I</td><td>IV</td><td>II</td></tr><tr><td>2.</td><td>IV</td><td>II</td><td>I</td><td>II</td></tr><tr><td>3.</td><td>IV</td><td>I</td><td>II</td><td>III</td></tr><tr><td>4.</td><td>IV</td><td>III</td><td>I</td><td>II</td></tr></tbody></table>
